def _read_current_json() -> List[Dict[str, Any]]:
    """
    Read the data table from current_json.json next to this test file.
    Expected format: list of case dicts, each may include:
      {
        "statusCode": <int>,       # required for expectations
        "scenario": "<name>",      # optional, used for test id
        "params": {
            "q": "<query string>",
            "lang": "<lang-code>"
        }
      }
    """
    path = Path(__file__).resolve().parent / "current_json.json"
    try:
        content = path.read_text(encoding="utf-8")
        data = json.loads(content)
        if isinstance(data, list):
            return data
        return []
    except FileNotFoundError:
        return []
    except Exception:
        return []


def pytest_generate_tests(metafunc):
    """
    Table-driven parameterization using current_json.json.
    Any test function that accepts a 'case' arg will be iterated over all rows in the JSON array.
    """
    if "case" in metafunc.fixturenames:
        dataset = _read_current_json()
        if not dataset:
            # Ensure at least one parameterization to show a clear skip reason during collection
            dataset = []
        ids = []
        for i, row in enumerate(dataset):
            scenario = row.get("scenario", f"case-{i}")
            status = row.get("statusCode", "unknown")
            ids.append(f"{scenario}-{status}")
        metafunc.parametrize("case", dataset, ids=ids, scope="function")


