def test_realtime_api_table_driven_status_and_schema(
    case: Dict[str, Any],
    api_client,
    default_params: Dict[str, Any],
    api_key_auth: str,
    swagger_validator: SwaggerSchemaValidator,
):
    """
    Table-driven test for GET /v1/current.json

    - Uses current_json.json for scenarios and expected status codes.
    - Validates request params prior to making the API call.
    - Validates response schema based on expected status.
    - Skips success scenario when required test data (e.g., 'q') is not present in current_json.json.
    - Skips authentication scenarios (401/403) as they are covered elsewhere.
    """
    if not case:
        pytest.skip("No cases provided in current_json.json")

    expected = case.get("statusCode", None)
    if expected is None:
        pytest.skip("Missing 'statusCode' in test case")

    if expected not in ALLOWED_STATUS_CODES:
        pytest.xfail(f"Status code {expected} is not defined by the endpoint spec; expected one of {sorted(ALLOWED_STATUS_CODES)}")

    # Build params from default and case
    params = _merge_params(default_params, case)

    # Handle per-expected behavior
    if expected == 200:
        # Prerequisites: require api key and 'q'
        if not api_key_auth:
            pytest.skip("ApiKeyAuth is not configured; skipping success scenario (401 tests handled elsewhere)")
        if "q" not in params or not str(params.get("q", "")).strip():
            pytest.skip("Missing 'q' in case params; add it to current_json.json to run success scenario")

        # Validate request parameters before sending
        swagger_validator.validate_with_schema(params, REQUEST_SCHEMA_REQUIRED_Q)

        # Make API call
        resp: Response = api_client.get(ENDPOINT, params=params)
        assert resp is not None, "No response returned by API client"
        assert resp.status_code == 200, f"Expected 200 OK, got {resp.status_code}. Body: {resp.text}"

        # Validate response JSON schema
        body = {}
        try:
            body = resp.json()
        except Exception:
            pytest.fail(f"Response is not valid JSON. Raw: {resp.text}")

        swagger_validator.validate_with_schema(body, RESPONSE_200_SCHEMA)

    elif expected == 400:
        # Validate request that may be missing 'q' or contain invalid values
        # Here we accept optional 'q' in request validation, as 400 responses can originate from invalid/missing inputs.
        swagger_validator.validate_with_schema(params, REQUEST_SCHEMA_OPTIONAL_Q)

        resp: Response = api_client.get(ENDPOINT, params=params)
        assert resp is not None, "No response returned by API client"
        assert resp.status_code == 400, f"Expected 400 Bad Request, got {resp.status_code}. Body: {resp.text}"

        # Validate error response schema
        body = {}
        try:
            body = resp.json()
        except Exception:
            pytest.fail(f"Response is not valid JSON. Raw: {resp.text}")

        swagger_validator.validate_with_schema(body, RESPONSE_ERROR_SCHEMA)

    elif expected in (401, 403):
        # Authentication tests are covered in a dedicated test file as per instructions.
        pytest.skip("Authentication/authorization scenarios are tested in test_authentication.py")


